#!/usr/bin/env python3
"""Generate Rune icons from the checked-in normalized SVG snapshot, without network IO."""

import argparse
from pathlib import Path
import re
import sys
import xml.etree.ElementTree as ET
from xml.sax.saxutils import escape

ROOT = Path(__file__).resolve().parent.parent
SOURCES = ROOT / "assets/icons"
OUTPUT = ROOT / "crates/pane-ui/src/icons.rs"
PRESENTATION = ("stroke", "stroke-width", "stroke-linecap", "stroke-linejoin", "fill")
SVG = "{http://www.w3.org/2000/svg}"
HEADER = """//! A subset of Lucide icons (<https://lucide.dev>, ISC licence) for Rune.
//! Generated by `python3 scripts/generate_icons.py` from `assets/icons/*.svg`.
//! See `assets/icons/README.md` for snapshot provenance and the supported SVG format.
use rune::Icon;

"""


def icon_body(source: Path) -> str:
    root = ET.fromstring(source.read_bytes())
    if root.tag != SVG + "svg" or root.get("viewBox") != "0 0 24 24":
        raise ValueError(f"{source}: expected an SVG with viewBox='0 0 24 24'")
    if set(root.attrib) - {"viewBox", *PRESENTATION}:
        raise ValueError(f"{source}: unsupported root attributes")
    if not len(root) or (root.text or "").strip():
        raise ValueError(f"{source}: expected shapes without text")
    shapes = []
    for child in root:
        if child.tag not in {SVG + tag for tag in ("path", "circle", "rect", "line")}:
            raise ValueError(f"{source}: unsupported shape {child.tag}")
        if len(child) or (child.text or "").strip() or (child.tail or "").strip():
            raise ValueError(f"{source}: expected flat shapes without text")
        attributes = dict(child.attrib)
        for name in PRESENTATION:
            if name in root.attrib:
                attributes.setdefault(name, root.attrib[name])
        if any("{" in name for name in attributes):
            raise ValueError(f"{source}: namespaced shape attributes are unsupported")
        attrs = "".join(
            f' {name}="{escape(value, {chr(34): "&quot;"})}"'
            for name, value in attributes.items()
        )
        shapes.append(f"<{child.tag.removeprefix(SVG)}{attrs}/>")
    body = "".join(shapes)
    ET.fromstring(f"<svg>{body}</svg>")
    return body


def generate(sources: Path = SOURCES) -> str:
    paths = sorted(sources.glob("*.svg"))
    if not paths:
        raise ValueError(f"{sources}: no SVG sources")
    output = [HEADER]
    for path in paths:
        name = path.stem
        if not re.fullmatch(r"[a-z][a-z0-9]*(?:-[a-z0-9]+)*", name):
            raise ValueError(f"{path}: expected a lowercase kebab-case icon name")
        body = icon_body(path)
        hashes = "#"
        while '"' + hashes in body:
            hashes += "#"
        output.append(
            f"pub static {name.upper().replace('-', '_')}: Icon = Icon {{\n"
            f'    name: "{name}",\n'
            "    view: 24.0,\n"
            f'    body: r{hashes}"{body}"{hashes},\n'
            "};\n"
        )
    return "".join(output)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail on drift without writing")
    args = parser.parse_args()
    try:
        generated = generate().encode("utf-8")
        current = OUTPUT.read_bytes() if OUTPUT.exists() else None
        if args.check:
            if generated != current:
                print("icons are out of date. Run python3 scripts/generate_icons.py", file=sys.stderr)
                return 1
        elif generated != current:
            OUTPUT.write_bytes(generated)
    except (OSError, ValueError, ET.ParseError) as error:
        print(f"generate_icons: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
